class Config(BaseModel):
    """Root configuration."""

    model: str = "deepseek/deepseek-chat"
    provider: str = "auto"
    workspace: str = ""
    sandbox: bool = True
    max_iterations: int = 100
    providers: dict[str, ProviderConfig] = Field(default_factory=dict)
    exec: ExecConfig = Field(default_factory=ExecConfig)
    memory: MemoryCompressionConfig = Field(default_factory=MemoryCompressionConfig)
    persistent_memory: PersistentMemoryConfig = Field(default_factory=PersistentMemoryConfig)

    def get_provider_config(self) -> ProviderConfig:
        """Resolve the provider config for the current model."""
        if self.provider != "auto" and self.provider in self.providers:
            return self.providers[self.provider]
        # auto-detect: try matching model prefix
        for name, cfg in self.providers.items():
            if cfg.api_key:
                return cfg
        return ProviderConfig()

    def get_workspace(self) -> Path:
        """Return the resolved workspace path."""
        if self.workspace:
            return Path(self.workspace).expanduser().resolve()
        return Path.cwd()

async def _run_streaming(self, user_message: str) -> AsyncIterator[str]:
    """Streaming agent loop. Yields content chunks."""
    await self._ensure_deps()
    self._last_run_usage.reset()
    messages: list[dict[str, Any]] = [
        {"role": "system", "content": self._build_system_prompt()},
        {"role": "user", "content": user_message},
    ]
    tools = self._registry.get_definitions()

    for i in range(self._config.max_iterations):
        context = AgentHookContext(iteration=i, messages=messages)

        if self._hook:
            await self._hook.before_iteration(context)

        response: LLMResponse | None = None
        content_parts: list[str] = []

        async for chunk_resp in self._provider.stream_chat(messages, tools):
            response = chunk_resp
            if chunk_resp.content:
                new = chunk_resp.content[len("".join(content_parts)):]
                if new:
                    content_parts.append(new)
                    yield new
            if chunk_resp.finish_reason:
                break

        if response:
            u = response.usage
            self._last_run_usage.add(u.prompt_tokens, u.completion_tokens, u.total_tokens)
            context.response = response
            context.tool_calls = list(response.tool_calls)

        if not response or not response.has_tool_calls:
            if self._hook:
                await self._hook.after_iteration(context)
                self._hook.finalize_content(context, response.content if response else "")
            return

        assistant_msg: dict[str, Any] = {"role": "assistant", "content": response.content or None}
        assistant_msg["tool_calls"] = [
            {
                "id": tc.id,
                "type": "function",
                "function": {
                    "name": tc.name,
                    "arguments": json.dumps(tc.arguments, ensure_ascii=False),
                },
            }
            for tc in response.tool_calls
        ]
        messages.append(assistant_msg)

        if self._hook:
            await self._hook.before_execute_tools(context)

        tool_results: list[str] = []
        tool_errors: list[str] = []
        for tc in context.tool_calls:
            args_preview = str(tc.arguments)[:200]
            console.print(f"  [bold blue]CALL {tc.name}[/bold blue]({args_preview})")
            result = await self._registry.execute(tc.name, tc.arguments)
            result_preview = (result[:300].replace("\n", " ") if result else "(empty)")
            try:
                print(f"    -> {result_preview}")
            except UnicodeEncodeError:
                enc = sys.stdout.encoding or "utf-8"
                safe = result_preview.encode(enc, errors="replace").decode(enc, errors="replace")
                print(f"    -> {safe}")
            tool_results.append(result)
            if result.startswith("Error"):
                tool_errors.append(result)
            messages.append({
                "role": "tool",
                "tool_call_id": tc.id,
                "content": result,
            })

        context.tool_results = tool_results
        context.tool_errors = tool_errors

        if self._hook:
            await self._hook.after_iteration(context)

    yield "Error: maximum tool iterations reached."

async def run_interactive(self) -> None:
    """Run an interactive chat session."""
    await self._ensure_deps()
    console.print("[bold green]toolsclaw[/bold green] - interactive mode (type 'exit' to quit)")
    console.print(f"Workspace: {self._workspace}\n")

    messages: list[dict[str, Any]] = [
        {"role": "system", "content": self._build_system_prompt()},
    ]
    tools = self._registry.get_definitions()

    while True:
        try:
            user_input = input("You: ").strip()
        except (EOFError, KeyboardInterrupt):
            console.print("\n[dim]Bye![/dim]")
            break

        if not user_input:
            continue
        if user_input.lower() in ("exit", "quit", "/exit", "/quit"):
            console.print("[dim]Bye![/dim]")
            break

        messages.append({"role": "user", "content": user_input})

        for i in range(self._config.max_iterations):
            context = AgentHookContext(iteration=i, messages=messages)

            if self._hook:
                await self._hook.before_iteration(context)

            # Log compression if it happened
            if self._hook and hasattr(self._hook, "compression_count"):
                from toolsclaw.hook import CompositeHook, MemoryCompressionHook
                mh = self._find_memory_hook(self._hook)
                if mh and mh.compression_count > 0 and mh.last_compressed_tokens > 0:
                    console.print(
                        f"  [dim]🧠 Memory compressed: "
                        f"{mh.compression_count}x, "
                        f"last saved ~{mh.last_compressed_tokens} tokens[/dim]"
                    )
                    mh.last_compressed_tokens = 0  # only log once per compression

class CompositeHook(AgentHook):
    """Fan-out hook that delegates to an ordered list of hooks."""

    __slots__ = ("_hooks",)

    def __init__(self, hooks: list[AgentHook]) -> None:
        super().__init__()
        self._hooks = list(hooks)

    async def before_iteration(self, context: AgentHookContext) -> None:
        for h in self._hooks:
            await h.before_iteration(context)

    async def before_execute_tools(self, context: AgentHookContext) -> None:
        for h in self._hooks:
            await h.before_execute_tools(context)

    async def after_iteration(self, context: AgentHookContext) -> None:
        for h in self._hooks:
            await h.after_iteration(context)

    def finalize_content(self, context: AgentHookContext, content: str | None) -> str | None:
        for h in self._hooks:
            content = h.finalize_content(context, content)
        return content

class MemoryCompressor:
    """Core memory compressor for conversation history.

    Provides multiple compression strategies and token estimation.

    Args:
        summarize_func: Optional async callable that takes a prompt string
            and returns a summary string. Required for ``summarize`` and
            ``hybrid`` strategies.
    """

    def __init__(
        self,
        summarize_func: Callable[[str], Awaitable[str]] | None = None,
    ) -> None:
        self._summarize_func = summarize_func

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def estimate_tokens(self, messages: list[dict[str, Any]]) -> int:
        """Estimate the total token count of a message list."""
        return estimate_messages_tokens(messages)

    def should_compress(
        self,
        messages: list[dict[str, Any]],
        threshold_tokens: int,
    ) -> bool:
        """Check if messages exceed the compression threshold."""
        return self.estimate_tokens(messages) > threshold_tokens

    async def compress(
        self,
        messages: list[dict[str, Any]],
        strategy: CompressionStrategy | str = CompressionStrategy.HYBRID,
        target_ratio: float = 0.5,
        min_rounds_to_keep: int = 3,
        tool_result_max_chars: int = _DEFAULT_TOOL_RESULT_MAX_CHARS,
    ) -> list[dict[str, Any]]:
        """Compress message history using the given strategy.

        Args:
            messages: The full message list (system + turns).
            strategy: Compression strategy to use.
            target_ratio: Target ratio of original size (0.0-1.0).
            min_rounds_to_keep: Minimum number of conversation rounds to keep.
            tool_result_max_chars: Max chars per tool result field.

        Returns:
            Compressed message list.
        """
        if isinstance(strategy, str):
            strategy = CompressionStrategy(strategy)

        if strategy == CompressionStrategy.DROP_TOOL_RESULTS:
            return _drop_tool_result_details(messages, tool_result_max_chars)

        if strategy == CompressionStrategy.TRUNCATE:
            return _truncate_rounds(messages, target_ratio, min_rounds_to_keep)

        if strategy == CompressionStrategy.SUMMARIZE:
            return await self._summarize_compress(
                messages, target_ratio, min_rounds_to_keep,
            )

        if strategy == CompressionStrategy.HYBRID:
            return await self._hybrid_compress(
                messages, target_ratio, min_rounds_to_keep, tool_result_max_chars,
            )

        return messages

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------

    async def _summarize_compress(
        self,
        messages: list[dict[str, Any]],
        target_ratio: float,
        min_rounds_to_keep: int,
    ) -> list[dict[str, Any]]:
        """Use LLM to summarize older rounds."""
        system_msgs = [m for m in messages if m.get("role") == "system"]
        non_system = [m for m in messages if m.get("role") != "system"]

        rounds = _group_into_rounds(non_system)
        total_rounds = len(rounds)

        if total_rounds <= min_rounds_to_keep:
            return messages

        keep = max(min_rounds_to_keep, int(total_rounds * target_ratio))
        keep = min(keep, total_rounds)

        to_summarize = rounds[:-keep]
        kept = rounds[-keep:]

        summary_text = self._make_fallback_summary(to_summarize)

        # If we have a summarize function, use it
        if self._summarize_func is not None:
            try:
                prompt = _build_summary_prompt(to_summarize)
                summary_text = await self._summarize_func(prompt)
            except Exception as exc:
                logger.warning(
                    "MemoryCompressor: LLM summarization failed (%s), "
                    "using fallback summary",
                    exc,
                )

        result = list(system_msgs)
        result.append({"role": "user", "content": summary_text})
        for group in kept:
            result.extend(group)

        logger.info(
            "MemoryCompressor: summarized %d rounds → 1 summary + %d rounds kept",
            len(to_summarize),
            len(kept),
        )

        return result

    async def _hybrid_compress(
        self,
        messages: list[dict[str, Any]],
        target_ratio: float,
        min_rounds_to_keep: int,
        tool_result_max_chars: int,
    ) -> list[dict[str, Any]]:
        """Hybrid: drop tool details first, then summarize if still over threshold."""
        result = _drop_tool_result_details(messages, tool_result_max_chars)

        # If still over threshold, summarize older rounds
        if self._summarize_func is not None:
            rounds = _group_into_rounds(
                [m for m in result if m.get("role") != "system"]
            )
            if len(rounds) > min_rounds_to_keep * 2:
                result = await self._summarize_compress(
                    result, target_ratio, min_rounds_to_keep,
                )
        else:
            # Fallback to truncation
            result = _truncate_rounds(result, target_ratio, min_rounds_to_keep)

        return result

    @staticmethod
    def _make_fallback_summary(
        rounds: list[list[dict[str, Any]]],
    ) -> str:
        """Generate a simple text summary without an LLM."""
        total_msgs = sum(len(g) for g in rounds)
        tools_used: set[str] = set()
        user_topics: list[str] = []

        for group in rounds:
            for msg in group:
                if msg.get("role") == "user":
                    content = msg.get("content", "")
                    if isinstance(content, str) and content:
                        user_topics.append(content[:120])
                tcs = msg.get("tool_calls")
                if isinstance(tcs, list):
                    for tc in tcs:
                        fn = tc.get("function", {})
                        if fn.get("name"):
                            tools_used.add(fn["name"])

        parts = [
            f"[Previous conversation: {len(rounds)} round(s), "
            f"{total_msgs} message(s).",
        ]
        if user_topics:
            topics = "; ".join(
                t.replace("\n", " ").strip()
                for t in user_topics[:5]
            )
            parts.append(f"Topics: {topics}")
        if tools_used:
            parts.append(f"Tools used: {', '.join(sorted(tools_used))}")
        parts.append("]")

class LLMProvider:
    """OpenAI-compatible LLM provider with tool calling support."""

    def __init__(self, config: Config) -> None:
        pcfg = config.get_provider_config()
        self._model = config.model
        self._client = AsyncOpenAI(
            api_key=pcfg.api_key or "none",
            base_url=pcfg.api_base or None,
        )

    async def chat(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]] | None = None,
    ) -> LLMResponse:
        """Send a chat completion request and parse the response."""
        kwargs: dict[str, Any] = {
            "model": self._model,
            "messages": messages,
        }
        if tools:
            kwargs["tools"] = tools
            kwargs["tool_choice"] = "auto"

        resp = await self._client.chat.completions.create(**kwargs)
        choice = resp.choices[0]
        msg = choice.message

        content = msg.content or ""
        tool_calls: list[ToolCallRequest] = []

        if msg.tool_calls:
            for tc in msg.tool_calls:
                try:
                    args = json.loads(tc.function.arguments)
                except (json.JSONDecodeError, TypeError):
                    args = {}
                tool_calls.append(
                    ToolCallRequest(id=tc.id, name=tc.function.name, arguments=args)
                )

        usage = TokenUsage()
        if resp.usage:
            usage = TokenUsage(
                prompt_tokens=resp.usage.prompt_tokens or 0,
                completion_tokens=resp.usage.completion_tokens or 0,
                total_tokens=resp.usage.total_tokens or 0,
            )

        return LLMResponse(
            content=content,
            tool_calls=tool_calls,
            finish_reason=choice.finish_reason or "",
            usage=usage,
        )

    async def stream_chat(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict[str, Any]] | None = None,
    ) -> AsyncIterator[LLMResponse]:
        """Stream a chat completion, yielding partial responses.

        Yields LLMResponse objects with incremental content.
        The final yield will have finish_reason set and usage populated.

        Usage::

            async for chunk in provider.stream_chat(messages, tools):
                if chunk.content:
                    print(chunk.content, end="", flush=True)
                if chunk.finish_reason:
                    print(f"\\n[Finished: {chunk.finish_reason}]")
        """
        kwargs: dict[str, Any] = {
            "model": self._model,
            "messages": messages,
            "stream": True,
        }
        if tools:
            kwargs["tools"] = tools
            kwargs["tool_choice"] = "auto"

        content_parts: list[str] = []
        tool_calls_buf: dict[int, dict[str, Any]] = {}  # index -> partial tc data
        finish_reason = ""
        usage = TokenUsage()

        async for chunk in await self._client.chat.completions.create(**kwargs):
            choice = chunk.choices[0]
            delta = choice.delta

            # accumulate content
            if delta.content:
                content_parts.append(delta.content)
                yield LLMResponse(content="".join(content_parts))

            # accumulate tool calls (streamed as they appear)
            if delta.tool_calls:
                for tc_delta in delta.tool_calls:
                    idx = tc_delta.index
                    if idx not in tool_calls_buf:
                        tool_calls_buf[idx] = {"id": "", "name": "", "arguments": ""}
                    if tc_delta.id:
                        tool_calls_buf[idx]["id"] = tc_delta.id
                    if tc_delta.function:
                        if tc_delta.function.name:
                            tool_calls_buf[idx]["name"] = tc_delta.function.name
                        if tc_delta.function.arguments:
                            tool_calls_buf[idx]["arguments"] += tc_delta.function.arguments

            # capture finish reason from last chunk
            if choice.finish_reason:
                finish_reason = choice.finish_reason

        # final: yield complete response with parsed tool calls
        full_content = "".join(content_parts)
        parsed_tool_calls: list[ToolCallRequest] = []
        for idx in sorted(tool_calls_buf.keys()):
            tc_data = tool_calls_buf[idx]
            try:
                args = json.loads(tc_data["arguments"])
            except (json.JSONDecodeError, TypeError):
                args = {}
            parsed_tool_calls.append(
                ToolCallRequest(id=tc_data["id"], name=tc_data["name"], arguments=args)
            )

        # consume usage from a non-streamed summary call if available
        # (most providers don't stream usage; fetch it separately if needed)
        yield LLMResponse(
            content=full_content,
            tool_calls=parsed_tool_calls,
            finish_reason=finish_reason,
            usage=usage,
        )

