        return {
            "type": "object",
            "properties": {
                "command": {
                    "type": "string",
                    "description": "The shell command to execute.",
                },
                "workdir": {
                    "type": "string",
                    "description": "Working directory (relative to workspace). Defaults to workspace root.",
                },
            },
            "required": ["command"],
        }

    def _check_deny(self, command: str) -> str | None:
        """Return an error message if the command matches a deny pattern."""
        for pattern in self._deny_patterns:
            if re.search(pattern, command):
                return f"Blocked by security policy: pattern '{pattern}'"
        return None

    def _resolve_workdir(self, workdir: str | None) -> Path:
        """Resolve and validate working directory stays within workspace."""
        if workdir:
            target = (self._workspace / workdir).resolve()
        else:
            target = self._workspace
        if not self._is_under(target, self._workspace):
            raise PermissionError(f"Working directory escapes workspace: {workdir}")
        return target

    @staticmethod
    def _is_under(path: Path, parent: Path) -> bool:
        try:
            path.relative_to(parent)
            return True
        except ValueError:
            return False

    async def execute(self, **kwargs: Any) -> str:
        command: str = kwargs.get("command", "")
        workdir: str | None = kwargs.get("workdir")

        if not command.strip():
            return "Error: empty command"

        deny = self._check_deny(command)
        if deny:
            return deny

        try:
            cwd = self._resolve_workdir(workdir)
        except PermissionError as e:
            return str(e)

        try:
            if sys.platform == "win32":
                proc = await asyncio.create_subprocess_shell(
                    command,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.STDOUT,
                    cwd=str(cwd),
                    env=self._build_env(),
                )
            else:
                proc = await asyncio.create_subprocess_shell(
                    command,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.STDOUT,
                    cwd=str(cwd),
                    env=self._build_env(),
                    executable="/bin/bash",
                )

            stdout, _ = await asyncio.wait_for(
                proc.communicate(), timeout=self._timeout
            )
            output = stdout.decode("utf-8", errors="replace") if stdout else ""

            # truncate very long output
            if len(output) > 10000:
                output = output[:5000] + "\n... (truncated) ...\n" + output[-5000:]

            exit_info = f"\n[exit code: {proc.returncode}]" if proc.returncode != 0 else ""
            return output + exit_info

        except asyncio.TimeoutError:
            return f"Error: command timed out after {self._timeout}s"
        except Exception as e:
            return f"Error: {e}"

    def _build_env(self) -> dict[str, str]:
        """Build environment for subprocess execution — inherit full parent env."""
        return dict(os.environ)

class RunScriptTool(Tool):
    """Execute a Python script using a skill's venv (for isolated dependencies)."""

    def __init__(self, workspace: Path, skills: list[Skill], timeout: int = 120) -> None:
        self._workspace = workspace.resolve()
        self._skills = {s.name: s for s in skills if s.available}
        self._skill_dirs = [s.path.parent.resolve() for s in skills]
        self._timeout = min(timeout, 600)

    @property
    def name(self) -> str:
        return "run_script"

    @property
    def description(self) -> str:
        names = ", ".join(self._skills.keys()) or "(none)"
        return (
            "Execute a Python script with a skill's isolated dependencies. "
            f"Available skills with venvs: {names}. "
            "If no skill is specified, uses the system Python."
        )

    @property
    def parameters(self) -> dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "script": {
                    "type": "string",
                    "description": "Path to the Python script (relative to workspace) or inline code.",
                },
                "skill": {
                    "type": "string",
                    "description": "Skill name whose venv to use. Omit to use system Python.",
                },
                "args": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Arguments to pass to the script.",
                },
                "inline": {
                    "type": "boolean",
                    "description": "If true, treat 'script' as inline Python code instead of a file path.",
                },
            },
            "required": ["script"],
        }

    async def execute(self, **kwargs: Any) -> str:
        script: str = kwargs.get("script", "")
        skill_name: str = kwargs.get("skill", "")
        args: list[str] = kwargs.get("args", [])
        inline: bool = kwargs.get("inline", False)

        # resolve python executable
        python_exe = sys.executable
        if skill_name:
            skill = self._skills.get(skill_name)
            if not skill:
                return f"Error: skill '{skill_name}' not found or unavailable"
            python_exe = skill.get_python()

        # build command
        if inline:
            cmd = [python_exe, "-c", script, *args]
        else:
            script_path = Path(script)
            if script_path.is_absolute() and script_path.exists():
                pass  # use as-is
            elif (self._workspace / script).exists():
                script_path = self._workspace / script
            else:
                # search skill directories
                for skill_dir in self._skill_dirs:
                    candidate = skill_dir / script
                    if candidate.exists():
                        script_path = candidate
                        break
                else:
                    return f"Error: script not found: {script} (searched workspace and skill dirs)"
            cmd = [python_exe, str(script_path), *args]

        try:
            proc = await asyncio.create_subprocess_exec(
                *cmd,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.STDOUT,
                cwd=str(self._workspace),
            )
            stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=self._timeout)
            output = stdout.decode("utf-8", errors="replace") if stdout else ""

            if len(output) > 10000:
                output = output[:5000] + "\n... (truncated) ...\n" + output[-5000:]

            exit_info = f"\n[exit code: {proc.returncode}]" if proc.returncode != 0 else ""
            return output + exit_info

        except asyncio.TimeoutError:
            return f"Error: script timed out after {self._timeout}s"
        except Exception as e:
            return f"Error: {e}"

class LoadSkillTool(Tool):
    """Load a skill's full content by name for immediate use."""

    def __init__(self, skills: list[Skill]) -> None:
        self._skills = {s.name: s for s in skills}

    @property
    def name(self) -> str:
        return "load_skill"

    @property
    def description(self) -> str:
        return (
            "Load a skill's full instructions by name. Use this when you identify "
            "a relevant skill from the skills summary. Returns the complete SKILL.md "
            "content with paths resolved."
        )

    @property
    def parameters(self) -> dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "skill_name": {
                    "type": "string",
                    "description": "The name of the skill to load (from the skills summary).",
                },
            },
            "required": ["skill_name"],
        }

    async def execute(self, **kwargs: Any) -> str:
        skill_name: str = kwargs.get("skill_name", "")

        if not skill_name:
            return "Error: skill_name is required"

        skill = self._skills.get(skill_name)
        if not skill:
            available = ", ".join(self._skills.keys())
            return f"Error: skill '{skill_name}' not found. Available skills: {available}"

        if not skill.available:
            missing = []
            if skill.requires.bins:
                missing.append(f"CLI tools: {', '.join(skill.requires.bins)}")
            if skill.requires.env:
                missing.append(f"env vars: {', '.join(skill.requires.env)}")
            return f"Error: skill '{skill_name}' is unavailable. Missing: {'; '.join(missing)}"

        # Replace {SKILL_DIR} with actual path
        skill_dir = str(skill.path.parent.resolve())
        content = skill.content.replace("{SKILL_DIR}", skill_dir)

        return content
